-- Class 12 (Pestiféré), built on class 6
DELETE FROM `playercreateinfo` WHERE `class` = 12;
-- Every race starts where race 1 class 1 does
INSERT INTO `playercreateinfo` (`race`, `class`, `map`, `zone`, `position_x`, `position_y`, `position_z`, `orientation`)
  SELECT `races`.`race`, 12, `start`.`map`, `start`.`zone`, `start`.`position_x`, `start`.`position_y`, `start`.`position_z`, `start`.`orientation`
  FROM (SELECT * FROM `playercreateinfo` WHERE `race` = 1 AND `class` = 1) `start`
  JOIN (SELECT DISTINCT `race` FROM `playercreateinfo` WHERE `race` IN (1, 2, 3, 4, 5, 6, 7, 8, 10, 11)) `races`;
DELETE FROM `player_class_stats` WHERE `Class` = 12;
INSERT INTO `player_class_stats` (`Class`, `Level`, `BaseHP`, `BaseMana`, `Strength`, `Agility`, `Stamina`, `Intellect`, `Spirit`)
  SELECT 12, `Level`, `BaseHP`, `BaseMana`, `Strength`, `Agility`, `Stamina`, `Intellect`, `Spirit` FROM `player_class_stats` WHERE `Class` = 6;
-- Levels the template class never sees (the Death Knight starts at 55) come from the start class, or the server refuses to start
INSERT INTO `player_class_stats` (`Class`, `Level`, `BaseHP`, `BaseMana`, `Strength`, `Agility`, `Stamina`, `Intellect`, `Spirit`)
  SELECT 12, `Level`, `BaseHP`, `BaseMana`, `Strength`, `Agility`, `Stamina`, `Intellect`, `Spirit` FROM (SELECT * FROM `player_class_stats` WHERE `Class` = 1) `fallback`
  WHERE `Level` NOT IN (SELECT `Level` FROM (SELECT `Level` FROM `player_class_stats` WHERE `Class` = 12) `have`);
