-- Class 13 (Nécromancien), built on class 9
DELETE FROM `playercreateinfo` WHERE `class` = 13;
INSERT INTO `playercreateinfo` (`race`, `class`, `map`, `zone`, `position_x`, `position_y`, `position_z`, `orientation`)
  SELECT `race`, 13, `map`, `zone`, `position_x`, `position_y`, `position_z`, `orientation` FROM `playercreateinfo` WHERE `class` = 9 AND `race` IN (1, 2, 3, 4, 5, 6, 7, 8, 10, 11);
-- Races the start class cannot be: a starting point belongs to the race, so any of its classes gives the same one
INSERT INTO `playercreateinfo` (`race`, `class`, `map`, `zone`, `position_x`, `position_y`, `position_z`, `orientation`)
  SELECT `p`.`race`, 13, `p`.`map`, `p`.`zone`, `p`.`position_x`, `p`.`position_y`, `p`.`position_z`, `p`.`orientation` FROM (SELECT * FROM `playercreateinfo`) `p`
  JOIN (SELECT `race`, MIN(`class`) AS `class` FROM `playercreateinfo` WHERE `race` IN (1, 2, 3, 4, 5, 6, 7, 8, 10, 11) GROUP BY `race`) `pick` ON `pick`.`race` = `p`.`race` AND `pick`.`class` = `p`.`class`
  WHERE `p`.`race` NOT IN (SELECT `race` FROM (SELECT `race` FROM `playercreateinfo` WHERE `class` = 13) `taken`);
